/**
 * @file mutexes.c
 * @author Alessandro Zingaretti | Polimarche Racing Team - UNIVPM
 * @brief Centralized mutex implementation for the MCU-ECU FreeRTOS system
 *
 * Provides thread-safe wrapper functions for all FreeRTOS mutexes used
 * throughout the MCU-ECU. The mutex handles themselves are created by
 * auto-generated code in main.c (from the .ioc file).
 *
 * Mutexes defined (from .ioc):
 *  - mutex_VehicleData       : Vehicle data structure protection
 *  - mutex_LPUART1           : LPUART1 serial communication protection
 *  - mutex_FDCAN1_MOTOR      : FDCAN1 motor controller communication protection
 *  - mutex_FDCAN2_MAIN       : FDCAN2 main controller communication protection
 */

#include "mutexes.h"
#include "cmsis_os.h"

/* =============================================================================
 *  MUTEX HANDLE DECLARATIONS (extern from main.c)
 * =============================================================================
 *  These handles are auto-generated by CubeMX from the .ioc file and
 *  initialized in the auto-generated code section of main.c.
 * ============================================================================= */

extern osMutexId_t mutex_VehicleDataHandle;
extern osMutexId_t mutex_LPUART1Handle;
extern osMutexId_t mutex_FDCAN1_MOTORHandle;
extern osMutexId_t mutex_FDCAN2_MAINHandle;

/* =============================================================================
 *  MUTEX WRAPPER IMPLEMENTATIONS
 * ============================================================================= */
/* ---- VEHICLE DATA -------------------------------------------------------- */
void Mutex_VehicleData_Lock(void)
{
    osMutexAcquire(mutex_VehicleDataHandle, osWaitForever);
}

void Mutex_VehicleData_Unlock(void)
{
    osMutexRelease(mutex_VehicleDataHandle);
}

/* ---- LPUART1 ------------------------------------------------------------- */
void Mutex_LPUART1_Lock(void)
{
    osMutexAcquire(mutex_LPUART1Handle, osWaitForever);
}

void Mutex_LPUART1_Unlock(void)
{
    osMutexRelease(mutex_LPUART1Handle);
}

/* ---- FDCAN1 MOTOR -------------------------------------------------------- */
void Mutex_FDCAN1_MOTOR_Lock(void)
{
    osMutexAcquire(mutex_FDCAN1_MOTORHandle, osWaitForever);
}

void Mutex_FDCAN1_MOTOR_Unlock(void)
{
    osMutexRelease(mutex_FDCAN1_MOTORHandle);
}

/* ---- FDCAN2 MAIN --------------------------------------------------------- */
void Mutex_FDCAN2_MAIN_Lock(void)
{
    osMutexAcquire(mutex_FDCAN2_MAINHandle, osWaitForever);
}

void Mutex_FDCAN2_MAIN_Unlock(void)
{
    osMutexRelease(mutex_FDCAN2_MAINHandle);
}



/* =============================================================================
 *  DIAGNOSTICS
 * ============================================================================= */

bool Mutex_IsInitialized(void)
{
    return (mutex_VehicleDataHandle      != NULL) &&
           (mutex_LPUART1Handle          != NULL) &&
           (mutex_FDCAN1_MOTORHandle     != NULL) &&
           (mutex_FDCAN2_MAINHandle      != NULL);
}
